using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace Vaanam.Core
{
    /// <summary>
    /// One place that plays music, sound effects and voice lines.
    ///
    /// - Voice lines come from Resources/Voice/{lang}/{key}.wav (English generated by
    ///   Tools/render-voice-lines.ps1; Tamil falls back to English until Tamil
    ///   recordings are added). Music ducks while a voice line plays.
    /// - Sound effects are generated by ProceduralAudio unless a clip is assigned.
    /// - Praise lines are rate-limited so the game does not nag.
    /// </summary>
    public class AudioDirector : MonoBehaviour
    {
        public static AudioDirector Instance { get; private set; }

        public enum Sfx { Chime, Sparkle, Whoosh, Bump, Jump, Duck, Fanfare, Hello }

        [Header("Optional overrides (leave empty to use generated sounds)")]
        [SerializeField] private AudioClip musicDay;
        [SerializeField] private AudioClip musicSunset;
        [SerializeField] private AudioClip chime, sparkle, whoosh, bump, jump, duck, fanfare, hello;

        [Header("Levels")]
        [SerializeField, Range(0f, 1f)] private float musicVolume = 0.55f;
        [SerializeField, Range(0f, 1f)] private float sfxVolume = 0.8f;
        [SerializeField, Range(0f, 1f)] private float voiceVolume = 1f;
        [SerializeField, Range(0f, 1f)] private float musicDuckWhileTalking = 0.3f;
        [Tooltip("Minimum seconds between two voice lines with the same key.")]
        [SerializeField] private float sameLineCooldown = 6f;

        private AudioSource _musicA, _musicB, _sfx, _voice;
        private readonly Dictionary<Sfx, AudioClip> _generated = new Dictionary<Sfx, AudioClip>();
        private readonly Dictionary<string, float> _lastSaid = new Dictionary<string, float>();
        private readonly Queue<string> _voiceQueue = new Queue<string>();
        private bool _sunset;
        private float _musicTarget = 1f;

        private void Awake()
        {
            if (Instance != null && Instance != this) { Destroy(gameObject); return; }
            Instance = this;

            _musicA = NewSource("MusicA", loop: true);
            _musicB = NewSource("MusicB", loop: true);
            _sfx = NewSource("Sfx", loop: false);
            _voice = NewSource("Voice", loop: false);
        }

        private AudioSource NewSource(string name, bool loop)
        {
            var go = new GameObject(name);
            go.transform.SetParent(transform, false);
            var s = go.AddComponent<AudioSource>();
            s.loop = loop; s.playOnAwake = false; s.spatialBlend = 0f;
            return s;
        }

        private void Start()
        {
            if (musicDay == null) musicDay = ProceduralAudio.MusicLoop(false);
            if (musicSunset == null) musicSunset = ProceduralAudio.MusicLoop(true);
            _musicA.clip = musicDay; _musicA.volume = 0f;
            _musicB.clip = musicSunset; _musicB.volume = 0f;
            if (SaveData.Current.MusicEnabled) _musicA.Play();
            StartCoroutine(VoicePump());
        }

        private void Update()
        {
            // Smooth music level: fades in, ducks under voice, swaps for sunset.
            float duck = _voice.isPlaying ? musicDuckWhileTalking : 1f;
            float target = SaveData.Current.MusicEnabled ? musicVolume * duck * _musicTarget : 0f;
            float a = _sunset ? 0f : target, b = _sunset ? target : 0f;
            _musicA.volume = Mathf.MoveTowards(_musicA.volume, a, Time.unscaledDeltaTime * 0.4f);
            _musicB.volume = Mathf.MoveTowards(_musicB.volume, b, Time.unscaledDeltaTime * 0.4f);
            if (_sunset && !_musicB.isPlaying && SaveData.Current.MusicEnabled) _musicB.Play();
            if (!_sunset && !_musicA.isPlaying && SaveData.Current.MusicEnabled) _musicA.Play();
        }

        /// <summary>Switch to the slow sunset music (or back).</summary>
        public void SetSunset(bool sunset) => _sunset = sunset;

        /// <summary>Overall music level multiplier, e.g. 0.4 while paused.</summary>
        public void SetMusicLevel(float level) => _musicTarget = Mathf.Clamp01(level);

        public void Play(Sfx kind, float volumeScale = 1f, float pitch = 1f)
        {
            AudioClip clip = Override(kind);
            if (clip == null)
            {
                if (!_generated.TryGetValue(kind, out clip) || clip == null)
                {
                    clip = Generate(kind);
                    _generated[kind] = clip;
                }
            }
            _sfx.pitch = pitch;
            _sfx.PlayOneShot(clip, sfxVolume * volumeScale);
        }

        private AudioClip Override(Sfx k) => k switch
        {
            Sfx.Chime => chime, Sfx.Sparkle => sparkle, Sfx.Whoosh => whoosh, Sfx.Bump => bump,
            Sfx.Jump => jump, Sfx.Duck => duck, Sfx.Fanfare => fanfare, Sfx.Hello => hello, _ => null
        };

        private static AudioClip Generate(Sfx k) => k switch
        {
            Sfx.Chime => ProceduralAudio.Chime(), Sfx.Sparkle => ProceduralAudio.Sparkle(),
            Sfx.Whoosh => ProceduralAudio.Whoosh(), Sfx.Bump => ProceduralAudio.Bump(),
            Sfx.Jump => ProceduralAudio.Jump(), Sfx.Duck => ProceduralAudio.Duck(),
            Sfx.Fanfare => ProceduralAudio.Fanfare(), Sfx.Hello => ProceduralAudio.Hello(), _ => ProceduralAudio.Chime()
        };

        /// <summary>
        /// Queue a voice line by L10n key. Lines never overlap; repeats of the same
        /// key are dropped while on cooldown. If there is no recording, nothing
        /// plays (the on-screen picture still shows), so missing audio never breaks play.
        /// </summary>
        public void Say(string key, bool important = false)
        {
            if (!SaveData.Current.VoiceEnabled) return;
            if (!important && _lastSaid.TryGetValue(key, out float t) && Time.unscaledTime - t < sameLineCooldown) return;
            _lastSaid[key] = Time.unscaledTime;
            if (important) { _voiceQueue.Clear(); _voice.Stop(); }
            if (_voiceQueue.Count < 3) _voiceQueue.Enqueue(key);
        }

        private IEnumerator VoicePump()
        {
            while (true)
            {
                if (_voiceQueue.Count > 0 && !_voice.isPlaying)
                {
                    string key = _voiceQueue.Dequeue();
                    AudioClip clip = L10n.Voice(key);
                    if (clip != null)
                    {
                        _voice.clip = clip; _voice.volume = voiceVolume; _voice.Play();
                        yield return new WaitForSecondsRealtime(clip.length + 0.25f);
                        continue;
                    }
                }
                yield return null;
            }
        }
    }
}
